    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LA_1RC1LC_0RD1RC_1LA1LD B0_0RB0LA_1RC1LC_0RD1RC_1LA1LD B1_0RB0LA_1RC1LC_0RD1RC_1LA1LD 4 14 p j' [] []).
    + exact run_ovf_0RB0LA_1RC1LC_0RD1RC_1LA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LA_1RC1LC_0RD1RC_1LA1LD p j' E).
    + exact (geo_0RB0LA_1RC1LC_0RD1RC_1LA1LD p j' E).
    + lia.
