(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LA_1RC1RB_1RD____1LA0LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_0RB0LA_1RC1RB_1RD____1LA0LB.
Proof.
  intros p j q0 E. destruct (BpCounter.cview_some_B p j q0 E) as (H1 & _).
  unfold Cc_0RB0LA_1RC1RB_1RD____1LA0LB, cden, A0_0RB0LA_1RC1RB_1RD____1LA0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LA_1RC1RB_1RD____1LA0LB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Bp q0 ++ [S0]) [] j A1_0RB0LA_1RC1RB_1RD____1LA0LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (BpCounter.cview_some_B p j q0 E) as (_ & H2).
  unfold Cc_0RB0LA_1RC1RB_1RD____1LA0LB, cden, A1_0RB0LA_1RC1RB_1RD____1LA0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LA_1RC1RB_1RD____1LA0LB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 6), (cden (Bp q0 ++ [S0]) [] j A1_0RB0LA_1RC1RB_1RD____1LA0LB).
  split; [lia|]. split; [| exact (gei_0RB0LA_1RC1RB_1RD____1LA0LB p j q0 E)].
  rewrite (gsi_0RB0LA_1RC1RB_1RD____1LA0LB p j q0 E).
  exact (srun_sound tm false true chi_0RB0LA_1RC1RB_1RD____1LA0LB A0_0RB0LA_1RC1RB_1RD____1LA0LB A1_0RB0LA_1RC1RB_1RD____1LA0LB 6 6
           run_int_0RB0LA_1RC1RB_1RD____1LA0LB (Bp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LA_1RC1RB_1RD____1LA0LB : forall p j, cview p = (S j, None) ->
