Lemma gsi_0RB0LA_1RC1RD_1LC1RB_0LD1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j A0_0RB0LA_1RC1RD_1LC1RB_0LD1LA.
