(** ** The lap *)

Lemma lap_0RB0LA_1RC1RD_1LC1RB_0LD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
