  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LA_1RC1RD_1LC1RB_0LD1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LA_1RC1RD_1LC1RB_0LD1LA B0_0RB0LA_1RC1RD_1LC1RB_0LD1LA B1_0RB0LA_1RC1RD_1LC1RB_0LD1LA 4 12 p j' [] []).
    + exact run_ovf_0RB0LA_1RC1RD_1LC1RB_0LD1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LA_1RC1RD_1LC1RB_0LD1LA p j' E).
    + exact (geo_0RB0LA_1RC1RD_1LC1RB_0LD1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LA_1RC1RD_1LC1RB_0LD1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
