    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LB_0RC1LD_1LB1RC_0RA1LA (StA, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LB_0RC1LD_1LB1RC_0RA1LA [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
