(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LB_1RC1LD_1LB1RC_0RC1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_0RB0LB_1RC1LD_1LB1RC_0RC1LA.
