Lemma geo_0RB0LB_1RC1LD_1LB1RC_0RC1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LB_1RC1LD_1LB1RC_0RC1LA) = lift (Cc (Pos.succ p)).
