  apply (fire_of_run_instr tm Cc true true l B0_0RB0LB_1RC1LD_1LB1RC_0RC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LB_1RC1LD_1LB1RC_0RC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LB_1RC1LD_1LB1RC_0RC1LA : forall t, ~ In t pins_0RB0LB_1RC1LD_1LB1RC_0RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LB_1RC1LD_1LB1RC_0RC1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LB_1RC1LD_1LB1RC_0RC1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LB_1RC1LD_1LB1RC_0RC1LA
      with (l := [SRotL 1; SWin 3; SCycL 3 0; SWin 6]).
