(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB0LC_0LC0RD_1LA1RA_1LC1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_0RB0LC_0LC0RD_1LA1RA_1LC1RB : srun tm true true chb_0RB0LC_0LC0RD_1LA1RA_1LC1RB B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB = Some (BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB, 4, 4).
