(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
