(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, A0_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ip q0 ++ [S0]) [] j A1_0RB0LC_0LC0RD_1LA1RA_1LC1RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, A1_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0LC_0LC0RD_1LA1RA_1LC1RB A0_0RB0LC_0LC0RD_1LA1RA_1LC1RB A1_0RB0LC_0LC0RD_1LA1RA_1LC1RB 4 4
             run_int_0RB0LC_0LC0RD_1LA1RA_1LC1RB (Ip q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j q0 E).
Qed.

Lemma gso_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_0LC0RD_1LA1RA_1LC1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_0LC0RD_1LA1RA_1LC1RB
             = (StA, (rep [S1;S0] (S j) ++ [S1;S0], S0, []))).
  { unfold cden, B1_0RB0LC_0LC0RD_1LA1RA_1LC1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, (rep [S1;S0] (S j) ++ [S1;S0], S0, []))).
  { unfold Cc_0RB0LC_0LC0RD_1LA1RA_1LC1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

Lemma gsn_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, AI0_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_0LC0RD_1LA1RA_1LC1RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, AI1_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_0LC0RD_1LA1RA_1LC1RB).
  split; [lia|]. split; [| exact (gen_0RB0LC_0LC0RD_1LA1RA_1LC1RB v i q0 E)].
  rewrite (gsn_0RB0LC_0LC0RD_1LA1RA_1LC1RB v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_0LC0RD_1LA1RA_1LC1RB AI0_0RB0LC_0LC0RD_1LA1RA_1LC1RB AI1_0RB0LC_0LC0RD_1LA1RA_1LC1RB 4 4
           run_inner_0RB0LC_0LC0RD_1LA1RA_1LC1RB (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall j, lift (cden [] [] j BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_0LC0RD_1LA1RA_1LC1RB. rewrite epow2_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_0LC0RD_1LA1RA_1LC1RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_0LC0RD_1LA1RA_1LC1RB, cden, BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_0LC0RD_1LA1RA_1LC1RB p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB).
    split; [lia|]. split; [| exact (gbo_0RB0LC_0LC0RD_1LA1RA_1LC1RB j)].
    rewrite (gso_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_0LC0RD_1LA1RA_1LC1RB B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB 4 4
             run_boot_0RB0LC_0LC0RD_1LA1RA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_0RB0LC_0LC0RD_1LA1RA_1LC1RB).
    split; [| exact (geo_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j E)].
    rewrite (gxi_0RB0LC_0LC0RD_1LA1RA_1LC1RB j).
    exact (srun_sound tm true true che_0RB0LC_0LC0RD_1LA1RA_1LC1RB BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB B1_0RB0LC_0LC0RD_1LA1RA_1LC1RB 4 10
             run_exit_0RB0LC_0LC0RD_1LA1RA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_0LC0RD_1LA1RA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_0LC0RD_1LA1RA_1LC1RB t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB). split;
      [| exact (gbo_0RB0LC_0LC0RD_1LA1RA_1LC1RB j)].
    rewrite (gso_0RB0LC_0LC0RD_1LA1RA_1LC1RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_0LC0RD_1LA1RA_1LC1RB B0_0RB0LC_0LC0RD_1LA1RA_1LC1RB BB1_0RB0LC_0LC0RD_1LA1RA_1LC1RB 4 4
             run_boot_0RB0LC_0LC0RD_1LA1RA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_0LC0RD_1LA1RA_1LC1RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_0LC0RD_1LA1RA_1LC1RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_0LC0RD_1LA1RA_1LC1RB : forall t, ~ In t pins_0RB0LC_0LC0RD_1LA1RA_1LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_0LC0RD_1LA1RA_1LC1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_0LC0RD_1LA1RA_1LC1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_0LC0RD_1LA1RA_1LC1RB (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_0LC0RD_1LA1RA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 6] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_0LC0RD_1LA1RA_1LC1RB (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_0LC0RD_1LA1RA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_0LC0RD_1LA1RA_1LC1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
