    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_0LC1RD_0RD1LA_1LC1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_0LC1RD_0RD1LA_1LC1RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_0LC1RD_0RD1LA_1LC1RB [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
