(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall j, lift (cden [] [] j BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_0LC1RD_1LA1LA_1LC1RB. rewrite epow2_0RB0LC_0LC1RD_1LA1LA_1LC1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_0LC1RD_1LA1LA_1LC1RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_0LC1RD_1LA1LA_1LC1RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_0LC1RD_1LA1LA_1LC1RB, cden, BE0_0RB0LC_0LC1RD_1LA1LA_1LC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_0LC1RD_1LA1LA_1LC1RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_0LC1RD_1LA1LA_1LC1RB p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB).
    split; [lia|]. split; [| exact (gbo_0RB0LC_0LC1RD_1LA1LA_1LC1RB j)].
    rewrite (gso_0RB0LC_0LC1RD_1LA1LA_1LC1RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_0LC1RD_1LA1LA_1LC1RB B0_0RB0LC_0LC1RD_1LA1LA_1LC1RB BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB 4 4
             run_boot_0RB0LC_0LC1RD_1LA1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_0RB0LC_0LC1RD_1LA1LA_1LC1RB).
    split; [| exact (geo_0RB0LC_0LC1RD_1LA1LA_1LC1RB p j E)].
