    exact (srun_sound tm true true che_0RB0LC_0LC1RD_1LA1LA_1LC1RB BE0_0RB0LC_0LC1RD_1LA1LA_1LC1RB B1_0RB0LC_0LC1RD_1LA1LA_1LC1RB 4 7
             run_exit_0RB0LC_0LC1RD_1LA1LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
