  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_0LC1RD_1LA1LA_1LC1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_0LC1RD_1LA1LA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
