(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_0LC1RD_1LA1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_0LC1RD_1LA1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_0LC1RD_1LA1LA_1LC1RB t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LC_0LC1RD_1LA1LA_1LC1RB). split;
      [| exact (gbo_0RB0LC_0LC1RD_1LA1LA_1LC1RB j)].
