Lemma mirror_ok_0RB0LC_0LC1RD_1RD1LA_1LC1RB : mirror_tm tm_0RB0LC_0LC1RD_1RD1LA_1LC1RB = tmm_0RB0LC_0LC1RD_1RD1LA_1LC1RB.
