Lemma fire_0RB0LC_1LA1RB_0RB1RD_1LD0LA : forall t, ~ In t pins_0RB0LC_1LA1RB_0RB1RD_1LD0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
