  - (* C0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_0RB0LC_1LA1RB_0RB1RD_1LD0LA (StC, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB0LC_1LA1RB_0RB1RD_1LD0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 4; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LA1RB_0RB1RD_1LD0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LA1RB_0RB1RD_1LD0LA
